    record,
    state: state,
    byId: byId,
    seqs: seqs,
    hiddenCallIds: hiddenCallIds,
    emit: emit,
  )) {
    return;
  }
  switch (record) {
    case HiddenRangeRecord():
      return;
    case CompactCheckpointRecord():
      _projectCheckpointRecord(
        record,
        state: state,
        byId: byId,
        seqs: seqs,
        emitted: emitted,
