import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_agent_harness/src/compaction/ledger_budget.dart';
import 'package:flutter_agent_harness/src/compaction/structured/markers.dart';

AssistantMessage _assistantWithTools(List<String> tools, DateTime at) =>
    AssistantMessage(
      content: [
        for (var i = 0; i < tools.length; i++)
          ToolCall(id: 'c$i', name: tools[i], arguments: const {}),
      ],
      api: 'test-api',
      provider: 'test-provider',
      model: 'test-model',
      usage: Usage.zero,
      stopReason: StopReason.stop,
      timestamp: at,
    );

MessageRecord _rec(String id, Message message, DateTime at) => MessageRecord(
      id: id,
      parentId: 'p',
      timestamp: at,
      message: message,
    );

void main() {
  print('=== round-1 findings vs the reworked code ===');

  // ── F1: long MCP-style tool names ──
  final label = toolHistogramLabel([
    _rec('a', _assistantWithTools(
        ['mcp__flutter_agent_harness__codegraph_callers'],
        DateTime.utc(2026, 11, 28, 12, 41)), DateTime.utc(2026, 11, 28, 12, 41)),
    _rec('b', _assistantWithTools(
        ['mcp__flutter_agent_harness__codegraph_impact_analysis'],
        DateTime.utc(2026, 11, 28, 13, 10)), DateTime.utc(2026, 11, 28, 13, 10)),
    _rec('c', _assistantWithTools(
        ['mcp__flutter_agent_harness__session_search_tool'],
        DateTime.utc(2026, 11, 28, 13, 44)), DateTime.utc(2026, 11, 28, 13, 44)),
  ]);
  print('F1 label (${label.length} chars): $label');
  final consolidated = consolidatedHideMarker(from: 142, to: 425, label: label);
  final collapsed = collapsedLedgerMarkerText(
    hiddenCount: 99,
    fromSeq: 142,
    toSeq: 425,
    label: label,
  );
  print('F1 consolidated (${consolidated.length}) '
      'predicate=${isCompactionMarkerText(consolidated)}');
  print('F1 collapsed  (${collapsed.length}) '
      'predicate=${isCompactionMarkerText(collapsed)}');
  print('F1 ledgerMarkerRef(consolidated) '
      'first=${ledgerMarkerRef(0, UserMessage.text(consolidated))?.firstSeq}');

  // ── F2: preview-quoted pointer ──
  final preview = markerPreview('see the fold quoted as [expand 3-140] above');
  final perRecord = hiddenMarker(
    seq: 142,
    kind: 'user',
    tokens: 1200,
    preview: preview,
  );
  final ref = ledgerMarkerRef(0, UserMessage.text(perRecord));
  print('F2 perRecord ref: first=${ref?.firstSeq} last=${ref?.lastSeq} '
      'count=${ref?.hiddenCount}');

  // ── F3: non-adjacent merge ──
  final markers = [
    UserMessage.text(hiddenMarker(seq: 5, kind: 'user', tokens: 100)),
    UserMessage.text('a visible user record sits here (never hidden)'),
    UserMessage.text(hiddenMarker(seq: 7, kind: 'user', tokens: 100)),
    UserMessage.text('[9:ckpt·38k→40tok·covers:9,10]'),
    UserMessage.text(hiddenMarker(seq: 12, kind: 'user', tokens: 100)),
  ];
  final out = collapseLedgerMarkers(markers, budget: 10, labelFor: (a, b) => '');
  print('F3 in=${markers.length} out=${out.messages.length} '
      'replacements=${out.replacementCount}');

  // ── NEW residual probe: 4+ digit hiddenCount vs the 21-char reserve ──
  print('=== residual: count-line width vs the reserve ===');
  for (final count in [99, 100, 560, 1120]) {
    final text = collapsedLedgerMarkerText(
      hiddenCount: count,
      fromSeq: 3,
      toSeq: 3 + count - 1,
      label: 'bash ×61 · read ×40 · edit ×12 · 12:41–13:44',
    );
    final head = text.replaceAll(RegExp(r' \[expand.*$'), '');
    print('count=$count headChars=${head.length} '
        'predicate=${isCompactionMarkerText(text)} '
        'ref=${ledgerMarkerRef(0, UserMessage.text(text))?.firstSeq}');
  }
}

